function summary=validate_hcp_stage3_rest_extended(workspace,out)
%VALIDATE_HCP_STAGE3_REST_EXTENDED ROI熵/ACF复用旧结果；新镜像体素只作未验证对称空间工程例。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function('D:/matlab/atoolbox/spm12');if nargin<2,out=fullfile(workspace,'derivatives','function_stage3_rest_extended_20261017');end;if isfolder(out),error('cog:Exists','Preserve successful output');end;mkdir(out);subjects=["100206";"100307";"100408"];manifest=table;pairManifest=table;first=fullfile(workspace,'derivatives','function_stage1_real_20261016');base=function_config;base.clean.bandHz=[.01 .08];
for k=1:3
    source=fullfile(first,'timeseries_results',subjects(k),'REST1_LR_prefix256','roi_timeseries.mat');s=load(source);data=struct('y',s.roi,'trSeconds',.72,'featureIds',"roi"+string(s.roiInfo.label),'frameIndices',(1:size(s.roi,1))','source',source,'processing',s.cleanInfo);file=fullfile(out,subjects(k)+"_roi.mat");save(file,'data');manifest=[manifest;table(subjects(k),"","REST1_LR_prefix256",string(file),'VariableNames',{'subject','session','run','data_file'})]; %#ok<AGROW>
    prepared=fullfile(first,'prepared',subjects(k));v=spm_vol(char(fullfile(prepared,'engineering_mask.nii')));mask=spm_read_vols(v)>0;ids=find(mask);[i,j,h]=ind2sub(v.dim,ids);world=v.mat*[i';j';h';ones(1,numel(ids))];left=find(world(1,:)<-2);xyz=world(:,left);xyz(1,:)=-xyz(1,:);mirror=v.mat\xyz;roundMirror=round(mirror(1:3,:));valid=all(abs(mirror(1:3,:)-roundMirror)<1e-6,1)&all(roundMirror>=1,1)&all(roundMirror<=v.dim(:),1);left=left(valid);roundMirror=roundMirror(:,valid);if numel(left)<8,error('cog:ExampleMirror','Insufficient exact-grid mirror candidates');end
    pick=round(linspace(1,numel(left),min(64,numel(left))));voxelPairs=[ids(left(pick)) sub2ind(v.dim,roundMirror(1,pick),roundMirror(2,pick),roundMirror(3,pick))'];paired=zeros(v.dim);paired(voxelPairs(:))=1;v.fname=char(fullfile(out,subjects(k)+"_paired_mask.nii"));v.dt=[16 0];v.pinfo=[1;0;0];spm_write_vol(v,paired);[y,space]=cog.load_bold(fullfile(prepared,'rest_prefix.nii'),v.fname,.72,1);[y,processing]=cog.clean_timeseries(y,.72,[],base.clean);[~,pairs]=ismember(voxelPairs,space.indices);
    data=struct('y',y,'trSeconds',.72,'featureIds',string(space.indices),'frameIndices',(1:size(y,1))','pairs',pairs,'space',space,'processing',processing,'mappingNote','Explicit world-x=0 grid mirror of sparse engineering points in published MNI data; no symmetric-template nonlinear registration verified.');file=fullfile(out,subjects(k)+"_paired.mat");save(file,'data');pairManifest=[pairManifest;table(subjects(k),"","REST1_LR_prefix256",string(file),'VariableNames',{'subject','session','run','data_file'})]; %#ok<AGROW>
end
file=fullfile(out,'roi_runs.tsv');writetable(manifest,file,'FileType','text','Delimiter','\t');c=rest_extended_config;c.manifestFile=file;c.outputRoot=fullfile(out,'metrics');c.execute=true;summary.metrics=run_rest_extended(c);file=fullfile(out,'pair_runs.tsv');writetable(pairManifest,file,'FileType','text','Delimiter','\t');c.manifestFile=file;c.outputRoot=fullfile(out,'homotopic_engineering');c.methods={'homotopic'};c.homotopic.mappingStatus='engineering_mirror';c.homotopic.mappingNote=data.mappingNote;c.homotopic.allowEngineeringMapping=true;summary.pairedMirror=run_rest_extended(c);
summary.skipped='Scientific verified-symmetric VMHC case: current HCP MNI inputs do not establish symmetric-template registration. Numerical paired correlation runs only under explicit engineering opt-in.';summary.scope='3 prefix256 REST runs/6 existing .01-.08Hz ROI series for distinct entropy/ACF metrics; up to64 exact-grid mirror pairs per subject for engineering paired r/maps, new voxels same explicit DCT preprocessing. No neural entropy/timescale or anatomically verified VMHC claim.';cog.write_json(fullfile(out,'VALIDATION.json'),summary);
end
